CREATE TABLE IF NOT EXISTS notification_campaigns (campaign_id INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id INTEGER NULL, name TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, audience_json TEXT NULL, recurrence TEXT NOT NULL DEFAULT 'once', parent_id INTEGER NULL, importance TEXT NOT NULL DEFAULT 'info', action_url TEXT NULL, expires_after_days INTEGER NOT NULL DEFAULT 0, template_id TEXT NOT NULL DEFAULT 'notification', channels_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', scheduled_at TEXT NULL, started_at TEXT NULL, completed_at TEXT NULL, created_by INTEGER NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_campaign_status ON notification_campaigns (tenant_id, status, scheduled_at);
CREATE TABLE IF NOT EXISTS notification_campaign_recipients (recipient_id INTEGER PRIMARY KEY AUTOINCREMENT, campaign_id INTEGER NOT NULL, channel TEXT NOT NULL, recipient TEXT NOT NULL, variables_json TEXT NULL, status TEXT NOT NULL DEFAULT 'pending', queued_jobs INTEGER NOT NULL DEFAULT 0, last_error TEXT NULL, processing_at TEXT NULL, queued_at TEXT NULL, created_at TEXT NOT NULL, UNIQUE (campaign_id, channel, recipient));
CREATE INDEX IF NOT EXISTS idx_campaign_recipient_status ON notification_campaign_recipients (campaign_id, status);
CREATE TABLE IF NOT EXISTS notification_campaign_rules (rule_id INTEGER PRIMARY KEY AUTOINCREMENT, scope_id INTEGER NOT NULL DEFAULT 0, rule_key TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 0, cooldown_days INTEGER NOT NULL DEFAULT 7, title TEXT NOT NULL, message TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (scope_id, rule_key));
CREATE TABLE IF NOT EXISTS notification_campaign_deliveries (delivery_id INTEGER PRIMARY KEY AUTOINCREMENT, scope_id INTEGER NOT NULL DEFAULT 0, rule_key TEXT NOT NULL, user_id INTEGER NOT NULL, event_id TEXT NOT NULL, source TEXT NOT NULL, notification_id INTEGER NULL, queued_at TEXT NOT NULL, UNIQUE (scope_id, rule_key, user_id));
CREATE TABLE IF NOT EXISTS notification_account_deactivations (user_id INTEGER PRIMARY KEY, deactivated_at TEXT NOT NULL, delete_at TEXT NOT NULL, confirmation_id INTEGER NULL, reminder_id INTEGER NULL, warning_id INTEGER NULL, status TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX IF NOT EXISTS idx_account_deactivation_due ON notification_account_deactivations (status, delete_at);
CREATE UNIQUE INDEX IF NOT EXISTS uq_campaign_occurrence ON notification_campaigns (parent_id, scheduled_at);
CREATE TABLE IF NOT EXISTS notification_campaign_recurrences (campaign_id INTEGER PRIMARY KEY, audience_json TEXT NOT NULL, next_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_automatic_campaign_history (history_id INTEGER PRIMARY KEY AUTOINCREMENT, scope_id INTEGER NOT NULL DEFAULT 0, run_key TEXT NOT NULL, rule_key TEXT NOT NULL, source TEXT NOT NULL, title TEXT NOT NULL, notification_id INTEGER NOT NULL UNIQUE, user_id INTEGER NOT NULL, queued_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_automatic_campaign_history_scope ON notification_automatic_campaign_history (scope_id, run_key, queued_at);
